// A function template whose noexcept status depends on its type T.

#include <utility>

struct ThrowableSwap { int val; };
void swap(ThrowableSwap&, ThrowableSwap&) { /* might throw */ }

struct NonThrowableSwap { int val; };
void swap(NonThrowableSwap&, NonThrowableSwap&) noexcept { /* can't throw */ }

// This function is noexcept only if the underlying swap is noexcept.
template <typename T>
void doSwap(T& a, T& b) noexcept(noexcept(swap(a, b)))
{
    swap(a, b);
}

void test() {
    ThrowableSwap a{}, b{};
    doSwap(a, b); // noexcept(doSwap) is false

    NonThrowableSwap x{}, y{};
    doSwap(x, y); // noexcept(doSwap) is true
}
